 passages=[
  ("Romans 14:10–12","S","Each one gives account of himself to God.",[("Romans",14,10,12)]),
  ("1 Corinthians 3:11–15","S","The work tried by fire; reward or loss; the builder himself saved.",[("1 Corinthians",3,11,15)]),
  ("2 Corinthians 5:10","S","“We must all appear before the judgment seat of Christ.”",[("2 Corinthians",5,10,10)]),
  ("Romans 8:1","S","No condemnation to them which are in Christ Jesus.",[("Romans",8,1,1)]),
  ("1 Thessalonians 5:9","S","God hath not appointed us to wrath.",[("1 Thessalonians",5,9,9)]),
 ],
