  ("Isaiah 9:6–7","S","The government upon His shoulder; the throne of David.",[("Isaiah",9,6,7)]),
  ("Daniel 7:13–14, 27","S","Dominion and a kingdom given; the saints possess it.",[("Daniel",7,13,14),("Daniel",7,27,27)]),
